import Foundation
import Testing
@testable import FirmingoKit

/// Independently authored synthetic metadata verifies catalogue trust/selection boundaries without boards or compilers.
struct ManagedCatalogueTests {
    /// Exact Python-generated byte hash, independent of the SDK manifest hasher/parser.
    private let catalogueHash = "7eb09989cbab271b0ba0350950fdc684a30a2ac2825488d58bcbfb3a32feba07"
    /// Independent canonical descriptor ID, covering metadata without any device identity.
    private let descriptorID = "818e03b95a375fdeeb584ec1daf7261561bf918255dec3b14fb3b22e75750d4d"
    /// Loads a packaged parser fixture, never a sibling checkout or executable hardware image.
    private func fixture(_ name: String) throws -> Data {
        let url = try #require(Bundle.module.url(forResource: name, withExtension: "json", subdirectory: "Fixtures/compiler-catalogue"))
        return try Data(contentsOf: url)
    }
    /// Builds mutation vectors from independent JSON, without the production descriptor encoder.
    private func fields() throws -> [String: Any] {
        try #require(JSONSerialization.jsonObject(with: fixture("descriptor")) as? [String: Any])
    }
    /// Serializes test mutations with explicit JSON types and optional manifest nesting.
    private func json(_ value: [String: Any]) throws -> Data { try JSONSerialization.data(withJSONObject: value, options: [.sortedKeys]) }
    /// Verifies mutated manifest bytes using a separately calculated host anchor solely for parser tests.
    private func load(_ entries: [[String: Any]]) async throws -> ManagedCompilerCatalogue {
        let data = try json(["schema": 1, "firmwareBuilds": entries])
        return try await ManagedCompilerCatalogue.load(manifestJSON: data, expectedSHA256: NanoManagedContract.digest(data))
    }

    /// Golden byte/descriptor identities resolve an explicit Nano choice and keep Pico unavailable.
    @Test func goldenCatalogue() async throws {
        let catalogue = try await ManagedCompilerCatalogue.load(manifestJSON: fixture("catalogue"), expectedSHA256: catalogueHash)
        #expect(catalogue.manifestSHA256 == catalogueHash)
        #expect(catalogue.firmwareBuilds.count == 1)
        let descriptor = try catalogue.build(id: descriptorID)
        #expect(descriptor == (try ManagedFirmwareBuildDescriptor(recordJSON: fixture("descriptor"))))
        #expect(descriptor.board == .nanoRP2040Connect)
        #expect(descriptor.profile == .nanoManagedV1)
        #expect(descriptor.apiAddress == 0x10022ca0)
        #expect(descriptor.qualification == "experimental")
        #expect(catalogue.builds(for: .nanoRP2040Connect) == [descriptor])
        #expect(catalogue.unavailableReason(for: .nanoRP2040Connect) == nil)
        #expect(catalogue.builds(for: .raspberryPiPico).isEmpty)
        #expect(catalogue.unavailableReason(for: .raspberryPiPico) != nil)
        #expect(throws: ManagedCatalogueError.missingBuild) { try catalogue.build(id: String(repeating: "f", count: 64)) }
    }
    /// Whitespace/key order changes alter catalogue bytes, but retain immutable semantic descriptor identity.
    @Test func descriptorCanonicalIdentity() async throws {
        let descriptor = try ManagedFirmwareBuildDescriptor(recordJSON: fixture("descriptor"))
        let compact = try json(fields())
        #expect(try ManagedFirmwareBuildDescriptor(recordJSON: compact).id == descriptorID)
        #expect(descriptor.id == descriptorID)
        #expect(compact != (try fixture("descriptor")))
        let reordered = try await load([fields()])
        #expect(reordered.firmwareBuilds[0].id == descriptorID)
        #expect(reordered.manifestSHA256 != catalogueHash)
    }
    /// Each declared build/provenance input changes identity even when the device and source are absent.
    @Test func everyBuildInputAffectsIdentity() throws {
        let vectors: [(String, Any)] = [("firmwareVersion", "0.1.0-m9exp2"), ("firmwareCommit", String(repeating: "3", count: 40)),
            ("residentELFSHA256", String(repeating: "4", count: 64)), ("firmwareImageSHA256", String(repeating: "5", count: 64)),
            ("buildReportSHA256", String(repeating: "6", count: 64)), ("apiAddress", 0x10020000)]
        var ids: Set<String> = [descriptorID]
        for (key, value) in vectors {
            var record = try fields(); record[key] = value
            #expect(ids.insert(try ManagedFirmwareBuildDescriptor(recordJSON: json(record)).id).inserted)
        }
    }
    /// Corruption and invalid trust-anchor spelling fail before schema parsing or any resource loading.
    @Test func integrityBoundary() async throws {
        let original = try fixture("catalogue")
        for hash in ["", String(repeating: "A", count: 64), String(repeating: "0", count: 64), String(repeating: "f", count: 63)] {
            await #expect(throws: ManagedCatalogueError.integrityMismatch) {
                try await ManagedCompilerCatalogue.load(manifestJSON: original, expectedSHA256: hash)
            }
        }
        await #expect(throws: ManagedCatalogueError.integrityMismatch) {
            try await ManagedCompilerCatalogue.load(manifestJSON: original + Data(" ".utf8), expectedSHA256: catalogueHash)
        }
    }
    /// Closed scalar/ABI/recipe fields reject unsupported boards, qualified claims and caller compiler flags.
    @Test func descriptorRejectionMatrix() throws {
        let vectors: [(String, Any)] = [("schema", true), ("schema", 2), ("board", "pico"), ("backend", "uart"),
            ("profile", "application"), ("residentABI", 2), ("targetID", 2), ("maximumCapsuleBytes", 4097),
            ("qualification", "qualified"), ("firmwareVersion", "version\n"), ("firmwareVersion", String(repeating: "v", count: 65)),
            ("firmwareCommit", String(repeating: "A", count: 40)), ("residentELFSHA256", "hash"),
            ("firmwareImageSHA256", String(repeating: "g", count: 64)), ("buildReportSHA256", NSNull()),
            ("apiAddress", false), ("apiAddress", -1), ("apiAddress", 0x10022ca1), ("apiAddress", 0x10200000),
            ("recipeIdentifier", "other-recipe"), ("recipeSHA256", String(repeating: "4", count: 64)), ("flags", ["-O0"])]
        for (key, invalid) in vectors {
            var record = try fields(); record[key] = invalid
            #expect(throws: ManagedCatalogueError.invalidDescriptor, "\(key) = \(invalid)") {
                try ManagedFirmwareBuildDescriptor(recordJSON: json(record))
            }
        }
        for key in try fields().keys {
            var record = try fields(); record.removeValue(forKey: key)
            #expect(throws: ManagedCatalogueError.invalidDescriptor) { try ManagedFirmwareBuildDescriptor(recordJSON: json(record)) }
        }
        #expect(throws: ManagedCatalogueError.invalidDescriptor) {
            try ManagedFirmwareBuildDescriptor(recordJSON: Data(repeating: 32, count: 4097))
        }
        let duplicate = try json(fields()).dropLast() + Data(",\"board\":\"pico\"}".utf8)
        #expect(throws: ManagedCatalogueError.invalidDescriptor) { try ManagedFirmwareBuildDescriptor(recordJSON: duplicate) }
    }
    /// Duplicate builds/conflicting image evidence fail; different complete images remain explicit choices.
    @Test func duplicateAndAmbiguousBuilds() async throws {
        let first = try fields()
        await #expect(throws: ManagedCatalogueError.invalidCatalogue) { try await load([first, first]) }
        var conflict = first; conflict["residentELFSHA256"] = String(repeating: "7", count: 64)
        await #expect(throws: ManagedCatalogueError.invalidCatalogue) { try await load([first, conflict]) }
        var second = conflict; second["firmwareImageSHA256"] = String(repeating: "8", count: 64)
        let catalogue = try await load([first, second])
        #expect(catalogue.builds(for: .nanoRP2040Connect).count == 2)
        #expect(try catalogue.build(id: descriptorID).residentELFSHA256 == String(repeating: "0", count: 64))
        let empty = try await load([])
        #expect(empty.firmwareBuilds.isEmpty)
        #expect(empty.unavailableReason(for: .nanoRP2040Connect) != nil)
        #expect(throws: ManagedCatalogueError.missingBuild) { try empty.build(id: descriptorID) }
    }
    /// Catalogue caps and closed schemas bound parser work and prohibit additive resource/path instructions.
    @Test func catalogueBoundsAndSchema() async throws {
        let descriptor = try fields()
        await #expect(throws: ManagedCatalogueError.invalidCatalogue) { try await load(Array(repeating: descriptor, count: 33)) }
        let boundary = (0..<32).map { index in
            var record = descriptor
            record["firmwareImageSHA256"] = String(format: "%064x", index + 10)
            return record
        }
        #expect(try await load(boundary).firmwareBuilds.count == 32)
        for root: [String: Any] in [["schema": false, "firmwareBuilds": []], ["schema": 2, "firmwareBuilds": []],
            ["schema": 1, "firmwareBuilds": "array"], ["schema": 1, "firmwareBuilds": [], "path": "../file"],
            ["firmwareBuilds": []], ["schema": 1, "firmwareBuilds": ["not a descriptor"]]] {
            let data = try json(root)
            await #expect(throws: ManagedCatalogueError.invalidCatalogue) {
                try await ManagedCompilerCatalogue.load(manifestJSON: data, expectedSHA256: NanoManagedContract.digest(data))
            }
        }
        let oversized = Data(repeating: 32, count: 128 * 1024 + 1)
        await #expect(throws: ManagedCatalogueError.invalidCatalogue) {
            try await ManagedCompilerCatalogue.load(manifestJSON: oversized, expectedSHA256: NanoManagedContract.digest(oversized))
        }
        let duplicate = Data("{\"schema\":1,\"schema\":1,\"firmwareBuilds\":[]}".utf8)
        await #expect(throws: ManagedCatalogueError.invalidCatalogue) {
            try await ManagedCompilerCatalogue.load(manifestJSON: duplicate, expectedSHA256: NanoManagedContract.digest(duplicate))
        }
    }
    /// Cancellation does not return verified metadata after the host withdraws the selection.
    @Test func cancelledCatalogue() async throws {
        let data = try fixture("catalogue"), hash = catalogueHash
        let task = Task {
            withUnsafeCurrentTask { $0?.cancel() }
            return try await ManagedCompilerCatalogue.load(manifestJSON: data, expectedSHA256: hash)
        }
        await #expect(throws: CancellationError.self) { try await task.value }
    }
    /// Exact synthetic persistence bytes restore a device association and adapt to legacy APIs without changing their schema.
    @Test func associationAndLegacyAdapter() throws {
        let bytes = try fixture("association")
        let association = try ManagedDeviceAssociation(recordJSON: bytes)
        #expect(try association.encodeRecord() == bytes)
        let descriptor = try ManagedFirmwareBuildDescriptor(recordJSON: fixture("descriptor"))
        let binding = try ManagedResidentBinding(association: association, firmwareBuild: descriptor)
        #expect(binding.deviceID == "0102030405060708")
        #expect(binding.residentELFSHA256 == descriptor.residentELFSHA256)
        #expect(binding.firmwareImageSHA256 == descriptor.firmwareImageSHA256)
        #expect(binding.apiAddress == descriptor.apiAddress)
        let other = try ManagedDeviceAssociation(deviceID: binding.deviceID, firmwareBuildID: String(repeating: "8", count: 64), evidence: .hostConfirmedExistingFirmware)
        #expect(throws: ManagedCatalogueError.associationMismatch) { try ManagedResidentBinding(association: other, firmwareBuild: descriptor) }
        let operation = UUID()
        let installed = try ManagedDeviceAssociation(deviceID: binding.deviceID, firmwareBuildID: descriptorID,
            evidence: .reviewedInstallationRecord, installationOperationID: operation)
        #expect(try ManagedDeviceAssociation(recordJSON: installed.encodeRecord()) == installed)
        #expect(installed.installationOperationID == operation)
    }
    /// Invalid persistence cannot fabricate a supported evidence kind, alter a descriptor or become an execution token.
    @Test func invalidAssociations() throws {
        let original = try #require(JSONSerialization.jsonObject(with: fixture("association")) as? [String: Any])
        let vectors: [(String, Any)] = [("version", false), ("version", 2), ("deviceID", "192.168.77.1"),
            ("firmwareBuildID", String(repeating: "A", count: 64)), ("evidence", "attested"),
            ("installationOperationID", UUID().uuidString), ("installationOperationID", NSNull()), ("extra", 1)]
        for (key, invalid) in vectors {
            var record = original; record[key] = invalid
            #expect(throws: ManagedCatalogueError.invalidAssociation) { try ManagedDeviceAssociation(recordJSON: json(record)) }
        }
        var missingOperation = original; missingOperation["evidence"] = "reviewedInstallationRecord"
        #expect(throws: ManagedCatalogueError.invalidAssociation) { try ManagedDeviceAssociation(recordJSON: json(missingOperation)) }
        #expect(throws: ManagedCatalogueError.invalidAssociation) {
            try ManagedDeviceAssociation(deviceID: "device", firmwareBuildID: descriptorID, evidence: .hostConfirmedExistingFirmware)
        }
        let duplicate = try fixture("association").dropLast() + Data(",\"deviceID\":\"1112131415161718\"}".utf8)
        #expect(throws: ManagedCatalogueError.invalidAssociation) { try ManagedDeviceAssociation(recordJSON: duplicate) }
        #expect(throws: ManagedCatalogueError.invalidAssociation) { try ManagedDeviceAssociation(recordJSON: Data(repeating: 32, count: 2049)) }
    }
}
